// Career mode content. A project is a story chapter with a report checklist; every item of the checklist is one task.
// Items keep to the order in which SQL is learned, and inside a project they get harder (d = 1..5).
// item: t = line on the checklist, c = concept lesson shown before the task (first time only), k = task id, d = difficulty, b = what the boss says.
// Task ids point to TASKS / EXERCISES (tasks.js, exercises.js) or to CAREER_TASKS below.
const BOSS = { name: "Ruth", role: "Head of Analytics" };

const CAREER_TASKS = [
 { id:"cx-01", db:"shop", topic:"basics", level:"easy", points:8, ordered:false, names:true,
   text:"Show each product's name and its price including 10 percent tax. Call the second column price_with_tax.",
   solution:"SELECT name, price * 1.1 AS price_with_tax FROM products", hint:"Write AS and the new name right after the calculation." },
 { id:"cx-02", db:"hr", topic:"sorting", level:"easy", points:10, ordered:true,
   text:"List all employees by department number (lowest first) and, inside each department, by salary from highest to lowest. Columns: name, department_id and salary.",
   solution:"SELECT name, department_id, salary FROM employees ORDER BY department_id ASC, salary DESC", hint:"Two sort keys, separated by a comma. DESC belongs to salary only." },
 { id:"cx-03", db:"shop", topic:"sorting", level:"easy", points:10, ordered:true,
   text:"The two cheapest Electronics products. Columns: name and price, cheapest first.",
   solution:"SELECT name, price FROM products WHERE category = 'Electronics' ORDER BY price ASC LIMIT 2", hint:"Filter first (WHERE), then sort, then cut with LIMIT." },
 { id:"cx-04", db:"lib", topic:"aggregates", level:"easy", points:10, ordered:false,
   text:"How many of our loans have already been returned? Count the loans that have a return date. Just the number.",
   solution:"SELECT COUNT(return_date) FROM loans", hint:"COUNT(column) skips the NULL values." },
 { id:"cx-05", db:"hr", topic:"filtering", level:"medium", points:12, ordered:false,
   text:"Show everyone whose job title contains 'Engineer' and who was hired in 2020 or later, plus anyone earning more than 200000. Columns: name and job_title.",
   solution:"SELECT name, job_title FROM employees WHERE (job_title LIKE '%Engineer%' AND hire_date >= '2020-01-01') OR salary > 200000", hint:"Put the AND part in brackets, then add OR salary > 200000." },
 { id:"cx-06", db:"shop", topic:"grouping", level:"medium", points:10, ordered:false,
   text:"For every product category: how many products we sell and their average price. Columns: category, number of products, average price.",
   solution:"SELECT category, COUNT(*), AVG(price) FROM products GROUP BY category", hint:"You can use several aggregates in one SELECT." },
 { id:"cx-07", db:"shop", topic:"joins", level:"medium", points:12, ordered:false,
   text:"For delivered orders: customer name, product name and quantity (in that order).",
   solution:"SELECT c.name, p.name, oi.quantity FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'delivered'", hint:"Start from order_items and add orders, customers and products one JOIN at a time." }
];

const CONCEPTS = {
 select: { t:"SELECT and FROM: reading a table", db:"shop",
  intro:"A database stores information in tables. A table is a grid: every column is one kind of fact (a name, a price) and every row is one thing (one product, one customer). SELECT says which columns you want to see, and FROM says which table to read them from.",
  syntax:"SELECT column1, column2\nFROM table_name;",
  pts:["SELECT * means 'every column'. It is the best way to take a first look at an unknown table.","Keywords such as SELECT and FROM are not case sensitive, but by convention they are written in capitals so they stand out.","A query only reads data. It never changes a table, so you cannot break anything by experimenting."],
  ex:{ sql:"SELECT * FROM products;", note:"Every column and every row of the products table. This is how you meet a new table." },
  watch:"SELECT * is fine for exploring. In a real report list the columns you need: wide tables can have dozens of columns and nobody wants to read them all." },
 columns: { t:"Choosing columns", db:"shop",
  intro:"Most of the time you only need a few columns. List them after SELECT, separated by commas. The result shows them in exactly the order you wrote them, so you can also use this to rearrange a table.",
  syntax:"SELECT name, city\nFROM customers;",
  pts:["Separate columns with commas, but never put a comma after the last one.","The order you write is the order you get: SELECT city, name shows the city first.","You can skip any column you do not need."],
  ex:{ sql:"SELECT name, city FROM customers;", note:"Two columns instead of four. The id and the signup date are simply left out." },
  watch:"A comma right before FROM (SELECT name, city, FROM customers) is the most common first error. SQL expects another column after every comma." },
 expr: { t:"Calculated columns", db:"shop",
  intro:"SELECT can do more than copy values: you can calculate with columns. Add (+), subtract (-), multiply (*) and divide (/). The calculation is done for every row and the result appears as a new column. The table itself does not change.",
  syntax:"SELECT name, price * 1.1\nFROM products;",
  pts:["Use + - * / and brackets, like a calculator. Brackets decide the order: (a + b) * c.","Multiply by 1.1 to add 10 percent, by 0.8 to take 20 percent off.","The new column gets an untidy automatic name such as price * 1.1. The next lesson shows how to name it."],
  ex:{ sql:"SELECT name, price, price * 1.1 FROM products;", note:"The third column is calculated from the second one, product by product." },
  watch:"Whole numbers divide in a whole-number way: in SQLite 7 / 2 gives 3, not 3.5. Write 7 / 2.0 when you want the decimals." },
 alias: { t:"AS: naming your columns", db:"shop",
  intro:"A column that comes out of a calculation gets an ugly name. AS gives any column a label of your choice. Reports are read by people, so price_with_tax says much more than price * 1.1. The label exists only in the result; the table is untouched.",
  syntax:"SELECT name, price * 1.1 AS price_with_tax\nFROM products;",
  pts:["Write AS and the new name directly after the column or calculation.","Use letters, digits and underscores, no spaces: price_with_tax, not price with tax.","It also works on plain columns (name AS product). Later you will use it for tables too."],
  ex:{ sql:"SELECT name AS product, price * 1.1 AS price_with_tax FROM products;", note:"Same data, but the headers now say what the columns mean." },
  watch:"In this task the checker also reads your column names, because naming is the whole point. Everywhere else only the values count." },
 distinct: { t:"DISTINCT: each value once", db:"shop",
  intro:"Some columns repeat the same value again and again. Three customers live in New York, but when someone asks 'which cities do we sell to?' they want each city once. DISTINCT, written right after SELECT, removes duplicate rows from the result.",
  syntax:"SELECT DISTINCT city\nFROM customers;",
  pts:["DISTINCT looks at the whole result row. With two columns it only removes rows where both values repeat.","It is the quickest way to find out which values a column contains.","The order of the rows is not guaranteed unless you add ORDER BY."],
  ex:{ sql:"SELECT DISTINCT city FROM customers;", note:"Eight customers, but only five different cities." },
  watch:"DISTINCT is not a cure for wrong results. If duplicates appear and you do not know why, find the reason first (usually a JOIN, which comes later)." },
 where: { t:"WHERE: keeping only some rows", db:"shop",
  intro:"A table can hold thousands of rows, and the question is almost never 'show me everything'. WHERE filters the rows: only those for which the condition is true are kept. The condition compares a column with a value.",
  syntax:"SELECT name, price\nFROM products\nWHERE price > 100;",
  pts:["Comparison operators: = equal, <> not equal, > greater, < less, >= greater or equal, <= less or equal.","SQL compares with a single =. There is no ==.","WHERE comes after FROM. The column you filter on does not have to appear in SELECT."],
  ex:{ sql:"SELECT name, price FROM products WHERE price > 100;", note:"Of 8 products, 5 pass the test. The cheap ones are not in the result." },
  watch:"Rows that fail the condition are not hidden, they are simply not in the result. The table keeps them." },
 text: { t:"Text values and quotes", db:"shop",
  intro:"Numbers are written as they are, but text goes between single quotes: city = 'Chicago'. Without the quotes SQL thinks Chicago is the name of a column and complains that it does not exist.",
  syntax:"SELECT name, city\nFROM customers\nWHERE city = 'Chicago';",
  pts:["Always single quotes for text values: 'Chicago'.","With = text is compared exactly, so 'chicago' does not match 'Chicago'.","<> means 'not equal': city <> 'Chicago' keeps everybody except Chicago."],
  ex:{ sql:"SELECT name, city FROM customers WHERE city = 'Chicago';", note:"Two customers live in Chicago." },
  watch:"A missing quote gives the error 'no such column: Chicago'. When 'no such column' names something that is really a value, add quotes." },
 dates: { t:"Dates are text too", db:"shop",
  intro:"This database stores a date as text in the form YYYY-MM-DD, for example '2024-04-01'. Because the year comes first, then the month, then the day, comparing dates as text puts them in the right order: > means later and < means earlier.",
  syntax:"SELECT id, order_date\nFROM orders\nWHERE order_date >= '2024-04-01';",
  pts:["Write dates as 'YYYY-MM-DD' including the zeros: '2024-04-01', not '2024-4-1'.","Dates need quotes, like any text.","order_date >= '2024-04-01' means the first of April or later; > would leave out the first itself."],
  ex:{ sql:"SELECT id, order_date FROM orders WHERE order_date >= '2024-04-01';", note:"The orders from April on." },
  watch:"A date such as 4/1/2024 would not compare correctly. A good database uses one format, and queries depend on it." },
 and: { t:"AND: all conditions must hold", db:"shop",
  intro:"Real questions have several conditions: 'furniture that costs more than 1000'. Join the conditions with AND. A row is kept only if every condition is true, so each extra AND makes the result smaller or equal.",
  syntax:"SELECT name, price\nFROM products\nWHERE category = 'Furniture'\n  AND price > 1000;",
  pts:["Put each condition on its own line. Long WHERE clauses stay readable.","Each side of AND is a full condition: price > 100 AND price < 500, not price > 100 AND < 500.","You can chain as many conditions as you need."],
  ex:{ sql:"SELECT name, price FROM products WHERE category = 'Furniture' AND price > 1000;", note:"Only the desk and the chair pass both tests." },
  watch:"The second condition needs the column again. 'AND < 500' on its own is an error." },
 or: { t:"OR and NOT", db:"shop",
  intro:"OR keeps a row when at least one condition is true: customers from New York or Chicago. It makes the result bigger. A single column holds one value, so 'city = A AND city = B' can never be true and returns nothing. That is the classic OR mistake.",
  syntax:"SELECT name, city\nFROM customers\nWHERE city = 'New York'\n   OR city = 'Chicago';",
  pts:["AND narrows, OR widens. Ask: must a row satisfy both, or either?","In everyday English 'New York and Chicago' means both cities, in SQL it is OR.","NOT turns a condition around: NOT city = 'Chicago' is the same as city <> 'Chicago'."],
  ex:{ sql:"SELECT name, city FROM customers WHERE city = 'New York' OR city = 'Chicago';", note:"Five customers live in one of the two cities." },
  watch:"When AND and OR meet, AND is evaluated first. Use brackets to say exactly what you mean: (a OR b) AND c." },
 between: { t:"BETWEEN: a range", db:"hr",
  intro:"For 'salary from 80000 to 100000' you could write two conditions with AND, but SQL has a shortcut. BETWEEN low AND high keeps the values from low up to high, and both ends are included.",
  syntax:"SELECT name, salary\nFROM employees\nWHERE salary BETWEEN 80000 AND 100000;",
  pts:["Both ends count: 80000 and 100000 themselves pass.","Put the smaller value first. BETWEEN 100000 AND 80000 finds nothing.","It works for numbers, dates and even text."],
  ex:{ sql:"SELECT name, salary FROM employees WHERE salary BETWEEN 80000 AND 100000;", note:"Four people earn in this range." },
  watch:"For dates that include a time of day the end point can surprise you. Here the dates have no time, so BETWEEN is safe." },
 in: { t:"IN: a list of values", db:"hr",
  intro:"'Departments in Austin or Seattle' needs an OR, and with more cities the condition gets long. IN (...) checks whether a value appears in a list and does the job in one short condition.",
  syntax:"SELECT name, location\nFROM departments\nWHERE location IN ('Austin', 'Seattle');",
  pts:["The list goes in brackets, values separated by commas, text in single quotes.","NOT IN (...) keeps everything that is not on the list.","IN is a tidy way of writing several OR conditions on the same column."],
  ex:{ sql:"SELECT name, location FROM departments WHERE location IN ('Austin', 'Seattle');", note:"Engineering sits in Austin, Support in Seattle." },
  watch:"IN compares one column with many values. It is not a way to compare many columns." },
 like: { t:"LIKE: searching in text", db:"hr",
  intro:"Sometimes you do not know the exact value: names that start with M, job titles that contain 'Lead'. LIKE compares text with a pattern, and the % sign stands for 'any characters, including none'.",
  syntax:"SELECT name, job_title\nFROM employees\nWHERE job_title LIKE '%Lead%';",
  pts:["'M%' starts with M, '%son' ends with son, '%Lead%' contains the word anywhere.","_ (underscore) matches exactly one character.","LIKE ignores upper and lower case for English letters in SQLite, unlike =."],
  ex:{ sql:"SELECT name, job_title FROM employees WHERE job_title LIKE '%Lead%';", note:"Everyone whose title contains the word Lead." },
  watch:"Wildcards only work with LIKE. job_title = '%Lead%' looks for a title that is literally %Lead%." },
 null: { t:"NULL: missing values", db:"lib",
  intro:"NULL means 'no value': unknown, or not there. A book that is still out has no return date, and the head of a company has no manager. NULL is not zero and not an empty text. It is the absence of a value, and it needs its own test.",
  syntax:"SELECT id, loan_date\nFROM loans\nWHERE return_date IS NULL;",
  pts:["Test with IS NULL and IS NOT NULL.","= NULL never matches anything, because 'unknown equals unknown' is not true, it is unknown.","In a result NULL is displayed as NULL, so you can spot it."],
  ex:{ sql:"SELECT id, loan_date FROM loans WHERE return_date IS NULL;", note:"Four loans have no return date: those books are still out." },
  watch:"WHERE return_date = NULL runs without an error and returns no rows at all. That silent failure is why 'use IS NULL' is a rule." },
 precedence: { t:"Mixing AND with OR", db:"hr",
  intro:"When AND and OR meet in one WHERE, SQL does the ANDs first, like multiplication before addition. That is rarely what a person means in words, so use brackets to make the grouping explicit.",
  syntax:"WHERE (job_title LIKE '%Engineer%'\n       AND hire_date >= '2020-01-01')\n   OR salary > 200000",
  pts:["Without brackets, a OR b AND c means a OR (b AND c).","Brackets cost nothing and remove doubt, even where they are not strictly needed.","Read the finished WHERE aloud as a sentence and check that it says what was asked."],
  ex:{ sql:"SELECT name, job_title, salary FROM employees\nWHERE (job_title LIKE '%Engineer%' AND hire_date >= '2020-01-01')\n   OR salary > 200000;", note:"Recent engineers, plus the two people on very high salaries." },
  watch:"a OR b AND c and (a OR b) AND c give different results, and a missing bracket does not produce an error. It is a silent bug." },
 order: { t:"ORDER BY: sorting", db:"shop",
  intro:"Without ORDER BY the database may return rows in any order. ORDER BY sorts the result by a column. By default it goes ascending (smallest first, A to Z, oldest first), and DESC reverses it.",
  syntax:"SELECT name, price\nFROM products\nORDER BY price DESC;",
  pts:["ASC (the default) is small to large, DESC is large to small.","ORDER BY is one of the last clauses: it comes after WHERE.","You can sort by a column you do not show."],
  ex:{ sql:"SELECT name, price FROM products ORDER BY price DESC;", note:"The most expensive product comes first." },
  watch:"The order of rows is only guaranteed when you ask for it. Do not rely on 'it usually comes out sorted'." },
 "order-multi": { t:"Sorting by several columns", db:"hr",
  intro:"When many rows share the first value, add a second sort key after a comma. SQL sorts by the first column, and only inside groups of equal values does it use the second. Each column has its own ASC or DESC.",
  syntax:"SELECT name, department_id, salary\nFROM employees\nORDER BY department_id ASC, salary DESC;",
  pts:["The first column decides, the second only breaks ties.","DESC applies to the column right before it, not to the ones that follow.","This is how 'by department and, inside each, by salary' is written."],
  ex:{ sql:"SELECT name, department_id, salary FROM employees ORDER BY department_id ASC, salary DESC;", note:"Departments in order, and inside each one the best paid first." },
  watch:"ORDER BY salary DESC, department_id is a different report: the department then only matters when two salaries are equal." },
 limit: { t:"LIMIT: the top N", db:"shop",
  intro:"A top-3 list is a sorted list cut off after three rows. LIMIT keeps only the first N rows of the result, so it almost always goes together with ORDER BY. Sort first, then cut.",
  syntax:"SELECT name, price\nFROM products\nORDER BY price DESC\nLIMIT 3;",
  pts:["The sort decides which rows are 'first'. Without ORDER BY the rows are arbitrary.","ORDER BY ... DESC LIMIT 3 is the top three, ORDER BY ... ASC LIMIT 3 the bottom three.","LIMIT is always the very last clause."],
  ex:{ sql:"SELECT name, price FROM products ORDER BY price DESC LIMIT 3;", note:"The three most expensive products." },
  watch:"If two rows tie for third place, LIMIT 3 keeps only one of them." },
 offset: { t:"OFFSET: skipping rows", db:"hr",
  intro:"OFFSET skips rows before LIMIT starts counting. LIMIT 1 OFFSET 1 means 'skip the first row, then take one', a neat way to ask for second place: the second-highest salary or the runner-up.",
  syntax:"SELECT salary\nFROM employees\nORDER BY salary DESC\nLIMIT 1 OFFSET 1;",
  pts:["OFFSET 0 skips nothing, OFFSET 10 skips ten rows.","Page 2 of a list with 20 rows per page is LIMIT 20 OFFSET 20.","OFFSET only makes sense with a stable ORDER BY."],
  ex:{ sql:"SELECT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1;", note:"The highest salary is skipped, so this is the second-highest." },
  watch:"This gives the second row, even if two people share the top salary. For the second-highest distinct value you would add DISTINCT." },
 agg: { t:"Aggregate functions: summarising rows", db:"shop",
  intro:"So far every query returned rows of a table. Aggregate functions boil many rows down to one answer: COUNT counts rows, SUM adds, AVG averages, MIN and MAX find the smallest and largest. 'How many products do we sell?' and 'what is the average price?' are aggregate questions.",
  syntax:"SELECT COUNT(*), AVG(price), MAX(price)\nFROM products;",
  pts:["COUNT(*) counts rows. SUM(col), AVG(col), MIN(col) and MAX(col) work on the values of one column.","WHERE runs first: AVG(price) with WHERE category = 'Electronics' averages only electronics.","Several aggregates in one SELECT give you one row with several numbers."],
  ex:{ sql:"SELECT COUNT(*), AVG(price), MAX(price) FROM products;", note:"One row: how many products, their average price and the highest price." },
  watch:"Do not put a plain column next to an aggregate (SELECT name, MAX(price)) until you learn GROUP BY. Most databases reject it, and SQLite lets it through with confusing results." },
 "count-distinct": { t:"COUNT(DISTINCT ...)", db:"shop",
  intro:"COUNT(column) counts rows, so a customer who ordered three times is counted three times. To count how many different values there are, put DISTINCT inside the brackets.",
  syntax:"SELECT COUNT(DISTINCT customer_id)\nFROM orders;",
  pts:["COUNT(customer_id) is the number of orders. COUNT(DISTINCT customer_id) is the number of different customers.","Use it for every 'how many different ...' question.","If a count looks too big, ask whether you counted rows when you meant different things."],
  ex:{ sql:"SELECT COUNT(*) AS orders, COUNT(DISTINCT customer_id) AS customers FROM orders;", note:"Twelve orders, but only seven different customers placed them." },
  watch:"COUNT(DISTINCT a, b) with two columns is not allowed in SQLite. Count one thing at a time." },
 "count-col": { t:"COUNT(*) versus COUNT(column)", db:"lib",
  intro:"COUNT(*) counts rows. COUNT(column) counts only the rows where that column is not NULL. That difference is useful: counting a column that is sometimes empty tells you how many rows have a value.",
  syntax:"SELECT COUNT(*), COUNT(return_date)\nFROM loans;",
  pts:["COUNT(*) counts every row, whatever it contains.","COUNT(return_date) skips the NULLs, so it counts the returned books only.","SUM, AVG, MIN and MAX also ignore NULL values."],
  ex:{ sql:"SELECT COUNT(*) AS all_loans, COUNT(return_date) AS returned FROM loans;", note:"Twelve loans, eight of them with a return date." },
  watch:"AVG ignores NULLs too, so the average is taken over the rows that have a value, not over all rows." },
 group: { t:"GROUP BY: one row per group", db:"shop",
  intro:"'How many customers per city?' is an aggregate question asked many times, once per city. GROUP BY splits the rows into groups by a column and runs the aggregate on each group separately: one result row per group.",
  syntax:"SELECT city, COUNT(*)\nFROM customers\nGROUP BY city;",
  pts:["Every column in SELECT must be in GROUP BY or inside an aggregate function.","Rows are filtered by WHERE first, then grouped.","Think of it as sorting rows into piles by city and then counting each pile."],
  ex:{ sql:"SELECT city, COUNT(*) FROM customers GROUP BY city;", note:"New York has three customers, every other city one or two." },
  watch:"Without GROUP BY the query returns a single row or a confusing one. You will meet that in a bug-fix task." },
 having: { t:"HAVING: filtering groups", db:"shop",
  intro:"WHERE filters rows before they are grouped, so it cannot see group results such as COUNT(*). HAVING filters the groups after they have been calculated: 'categories with more than 2 products'.",
  syntax:"SELECT category, COUNT(*)\nFROM products\nGROUP BY category\nHAVING COUNT(*) > 2;",
  pts:["The order in a query: WHERE, GROUP BY, HAVING, ORDER BY.","WHERE is for conditions on single rows, HAVING for conditions on aggregates.","You can use both in the same query."],
  ex:{ sql:"SELECT category, COUNT(*) FROM products GROUP BY category HAVING COUNT(*) > 2;", note:"Stationery has only two products, so it drops out." },
  watch:"WHERE COUNT(*) > 2 is an error ('misuse of aggregate'): at the WHERE step the counts do not exist yet." },
 "group-expr": { t:"Grouping by a calculation", db:"shop",
  intro:"You can group by an expression, not only by a column. A very common one is the month of a date: strftime('%Y-%m', order_date) turns '2024-03-12' into '2024-03', so every order of March lands in the same group.",
  syntax:"SELECT strftime('%Y-%m', order_date), COUNT(*)\nFROM orders\nGROUP BY strftime('%Y-%m', order_date);",
  pts:["strftime('%Y', d) gives the year, '%m' the month, '%Y-%m' the year and month.","Repeat the same expression in SELECT and in GROUP BY.","Orders per month, hires per year and loans per week all work this way."],
  ex:{ sql:"SELECT strftime('%Y-%m', order_date) AS month, COUNT(*) AS orders FROM orders GROUP BY strftime('%Y-%m', order_date);", note:"One row per month of 2024." },
  watch:"The format codes are case sensitive: %m is the month, %M is the minutes." },
 join: { t:"JOIN: combining tables", db:"lib",
  intro:"Data is split into tables so that nothing is stored twice: a book only keeps an author_id, and the author's name lives in the authors table. To show a book together with its author, JOIN links the tables. ON says how: the book's author_id must equal the author's id.",
  syntax:"SELECT b.title, a.name\nFROM books b\nJOIN authors a ON a.id = b.author_id;",
  pts:["A column that points to another table's id is a foreign key: author_id points to authors.id.","The short names after the tables (b, a) are aliases. Prefix columns with them (a.name) so SQL knows which table you mean.","JOIN keeps only rows that have a match on both sides."],
  ex:{ sql:"SELECT b.title, a.name FROM books b JOIN authors a ON a.id = b.author_id;", note:"Every book is now shown with the name of its author." },
  watch:"A JOIN without a correct ON pairs every row with every row, and the result explodes. If the number of rows looks silly, check your ON." },
 "join-chain": { t:"Joining three tables", db:"shop",
  intro:"Sometimes the data you need is two steps away. An order line knows its order and its product; the customer is reached through the order. You chain JOINs: each one adds one more table, linked through its keys.",
  syntax:"SELECT c.name AS customer, p.name AS product, oi.quantity\nFROM order_items oi\nJOIN orders o    ON o.id = oi.order_id\nJOIN customers c ON c.id = o.customer_id\nJOIN products p  ON p.id = oi.product_id;",
  pts:["Start from the table with the most detail (order_items) and add the others.","Every JOIN has its own ON.","Sketch the tables and the arrows between them first. The query follows the arrows."],
  ex:{ sql:"SELECT c.name AS customer, p.name AS product, oi.quantity\nFROM order_items oi\nJOIN orders o    ON o.id = oi.order_id\nJOIN customers c ON c.id = o.customer_id\nJOIN products p  ON p.id = oi.product_id;", note:"Who bought what, in what quantity: four tables, one report." },
  watch:"Two columns both called name are confusing in a report. Label them with AS." },
 "left-join": { t:"LEFT JOIN: keep the unmatched rows", db:"shop",
  intro:"A normal JOIN drops rows without a partner: a customer who never ordered disappears from a customers-with-orders list. LEFT JOIN keeps every row of the left table and fills the right side with NULL where nothing matches. That makes it perfect for 'who has never ...' questions.",
  syntax:"SELECT c.name, o.id\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.id IS NULL;",
  pts:["The left table is the one written after FROM.","Rows without a match have NULL in the columns of the right table.","WHERE o.id IS NULL then keeps exactly the customers with no orders."],
  ex:{ sql:"SELECT c.name, o.id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;", note:"One customer has never placed an order. Without the WHERE you would see every customer, with NULL for that one." },
  watch:"A WHERE condition on a column of the right table (other than IS NULL) turns the LEFT JOIN back into an ordinary JOIN." },
 "self-join": { t:"Joining a table to itself", db:"hr",
  intro:"Some tables point to themselves: employees.manager_id holds the id of another employee, the boss. To show a person next to their manager's name, you join employees to employees: once as e for the employee and once as m for the manager. Aliases make this possible.",
  syntax:"SELECT e.name AS employee, m.name AS manager\nFROM employees e\nJOIN employees m ON m.id = e.manager_id;",
  pts:["The same table appears twice with different aliases.","m.id = e.manager_id reads: 'the manager of e is the person m'.","People without a manager disappear with JOIN. Use LEFT JOIN to keep them."],
  ex:{ sql:"SELECT e.name AS employee, m.name AS manager FROM employees e JOIN employees m ON m.id = e.manager_id;", note:"Eight people have a manager, five (the heads) do not and are missing here." },
  watch:"Without aliases SQL cannot tell the two copies apart and reports 'ambiguous column name'." },
 "join-group": { t:"JOIN plus GROUP BY: real reports", db:"shop",
  intro:"Most business reports combine both tricks: join the tables to bring the facts together, then group to summarise. Revenue per category needs the order lines (quantities) and the products (prices and categories): JOIN, multiply, SUM, GROUP BY.",
  syntax:"SELECT p.category, SUM(oi.quantity * p.price)\nFROM order_items oi\nJOIN products p ON p.id = oi.product_id\nGROUP BY p.category;",
  pts:["Build it in steps: first the JOIN with all the columns, then add GROUP BY and the aggregates.","You can calculate inside an aggregate: SUM(quantity * price).","Filter rows with WHERE before grouping, filter groups with HAVING after."],
  ex:{ sql:"SELECT p.category, SUM(oi.quantity * p.price) AS revenue FROM order_items oi JOIN products p ON p.id = oi.product_id GROUP BY p.category;", note:"Revenue per category across all order lines." },
  watch:"A join repeats rows: an order with three lines appears three times, so COUNT(*) may count lines when you meant orders." },
 "subquery-scalar": { t:"Subqueries: a query inside a query", db:"shop",
  intro:"'Products priced above the average' takes two steps: find the average, then compare. A subquery in brackets lets one query use the result of another. If the inner query returns a single value, you can use it like a number.",
  syntax:"SELECT name, price\nFROM products\nWHERE price > (SELECT AVG(price) FROM products);",
  pts:["The inner query runs first and must return one value.","The brackets are required.","The report stays correct when the data changes, because the average is calculated again."],
  ex:{ sql:"SELECT name, price FROM products WHERE price > (SELECT AVG(price) FROM products);", note:"The average price is 1012.5, so only three products are above it." },
  watch:"WHERE price > AVG(price) is not allowed: aggregates cannot be used directly in WHERE. A subquery is the way around it." },
 "subquery-in": { t:"IN with a subquery", db:"shop",
  intro:"When the inner query returns a list of values, use IN. 'Customers who have a cancelled order': first find the customer ids on cancelled orders, then keep the customers whose id is in that list.",
  syntax:"SELECT name\nFROM customers\nWHERE id IN (\n  SELECT customer_id FROM orders\n  WHERE status = 'cancelled'\n);",
  pts:["The inner query must return exactly one column.","NOT IN reverses it: customers without any cancelled order.","It never duplicates rows, which a JOIN sometimes does."],
  ex:{ sql:"SELECT name FROM customers WHERE id IN (SELECT customer_id FROM orders WHERE status = 'cancelled');", note:"Two customers have had an order cancelled." },
  watch:"NOT IN has a trap: if the inner list contains a NULL, NOT IN returns no rows at all. Filter NULLs out of the subquery or use NOT EXISTS." },
 exists: { t:"EXISTS: is there a matching row?", db:"lib",
  intro:"EXISTS asks a yes-or-no question for every row of the outer query: does the inner query find at least one row? The inner query can look at the current outer row (a correlated subquery). NOT EXISTS is the clean way to say 'has none'.",
  syntax:"SELECT name\nFROM members m\nWHERE NOT EXISTS (\n  SELECT 1 FROM loans l\n  WHERE l.member_id = m.id\n);",
  pts:["SELECT 1 in the inner query is a habit: only the existence of a row matters, not its columns.","The inner query refers to the outer row (m.id), so it is evaluated for each member.","NOT EXISTS does not have the NULL trap of NOT IN."],
  ex:{ sql:"SELECT name FROM members m WHERE NOT EXISTS (SELECT 1 FROM loans l WHERE l.member_id = m.id);", note:"One member has never borrowed a book." },
  watch:"Forget the link between inner and outer (l.member_id = m.id) and the inner condition is the same for every row." },
 case: { t:"CASE: if / else inside SQL", db:"shop",
  intro:"CASE builds a new column from rules, like an IF in a spreadsheet. SQL checks the WHEN conditions from top to bottom and returns the value of the first one that is true. ELSE covers everything else.",
  syntax:"SELECT name, price,\n  CASE WHEN price >= 1000 THEN 'expensive'\n       WHEN price >= 100  THEN 'mid-range'\n       ELSE 'cheap'\n  END AS price_band\nFROM products;",
  pts:["The first true WHEN wins, so put the strictest condition first.","Always finish with END, and add an ELSE; without it unmatched rows get NULL.","Label the new column with AS."],
  ex:{ sql:"SELECT name, price,\n  CASE WHEN price >= 1000 THEN 'expensive'\n       WHEN price >= 100  THEN 'mid-range'\n       ELSE 'cheap'\n  END AS price_band\nFROM products;", note:"Every product gets a label based on its price." },
  watch:"If the conditions overlap, the order of the WHEN lines changes the result." },
 cte: { t:"WITH: naming a step (CTE)", db:"shop",
  intro:"Long queries get hard to read. WITH gives a sub-result a name so you can build a report in readable steps: first define order_values, then use it like a table. It does the same as a subquery, but reads top to bottom.",
  syntax:"WITH order_values AS (\n  SELECT oi.order_id, SUM(oi.quantity * p.price) AS value\n  FROM order_items oi\n  JOIN products p ON p.id = oi.product_id\n  GROUP BY oi.order_id\n)\nSELECT order_id, value\nFROM order_values\nWHERE value > 1000;",
  pts:["WITH name AS ( query ) comes before the main SELECT.","Use the name like a table, even several times.","Several steps can follow each other, separated by commas."],
  ex:{ sql:"WITH order_values AS (\n  SELECT oi.order_id, SUM(oi.quantity * p.price) AS value\n  FROM order_items oi\n  JOIN products p ON p.id = oi.product_id\n  GROUP BY oi.order_id\n)\nSELECT order_id, value\nFROM order_values\nWHERE value > 1000;", note:"First every order's value is calculated, then the big orders are picked out." },
  watch:"A CTE exists only for this one query. It is not stored in the database." },
 window: { t:"Window functions: RANK", db:"shop",
  intro:"GROUP BY collapses rows into one per group. Sometimes you want to keep every row and still compare it with its group: 'rank the products by price inside each category'. A window function does that. OVER defines the window, PARTITION BY splits it into groups, ORDER BY sorts inside each.",
  syntax:"SELECT name, category, price,\n  RANK() OVER (PARTITION BY category\n               ORDER BY price DESC) AS rank_in_category\nFROM products;",
  pts:["PARTITION BY is like GROUP BY for the window, but the rows stay.","RANK() gives equal values the same number and then skips: 1, 2, 2, 4.","Without PARTITION BY the window is the whole table."],
  ex:{ sql:"SELECT name, category, price,\n  RANK() OVER (PARTITION BY category ORDER BY price DESC) AS rank_in_category\nFROM products;", note:"Every product with its place inside its own category." },
  watch:"You cannot filter on a window function in the WHERE of the same query. To keep only rank 1, wrap the query in a subquery or a CTE." },
 running: { t:"Running totals", db:"hr",
  intro:"Put an aggregate such as SUM in front of OVER (ORDER BY ...) and it becomes a running total: for each row, the sum of that row and all the rows before it in the chosen order. It shows how a number builds up over time.",
  syntax:"SELECT name, hire_date, salary,\n  SUM(salary) OVER (ORDER BY hire_date) AS payroll_so_far\nFROM employees;",
  pts:["The ORDER BY inside OVER decides what 'before' means.","Each row keeps its own values and gains the running total.","For a separate total per group, add PARTITION BY."],
  ex:{ sql:"SELECT name, hire_date, salary,\n  SUM(salary) OVER (ORDER BY hire_date) AS payroll_so_far\nFROM employees;", note:"The payroll grows with every hire." },
  watch:"Rows with the same date are treated together, so their running totals are equal. Add a unique column to the sort if that matters." }
};

